void Solver::bump_var(int var, double coeff) {
    // Scale coefficient by base factor
    double scaled_coeff = coeff * var_inc;
    // Add scaled activity
    activity[var] += scaled_coeff;

    // Periodically decay all activities to maintain numerical stability
    if (activity[var] > 1e100) {
        for (int i = 1; i <= vars; i++) {
            activity[i] *= 1e-100;
        }
        var_inc *= 1e-100;
    }

    // Update heap position if variable is in heap
    if (vsids.inHeap(var)) {
        vsids.update(var);
    }
}
